// Full Response wraps the login call as { statusCode, headers, body }.
// set-cookie can be a single string or an array depending on the HTTP
// client layer -- handle both rather than assume one.
const headers = $json.headers || {};
const raw = headers['set-cookie'];
const setCookie = Array.isArray(raw) ? raw[0] : raw;
if (!setCookie) {
  throw new Error('login did not return a session cookie -- check DASHBOARD_LOGIN_SECRET and DASHBOARD_BASE_URL');
}
const cookie = setCookie.split(';')[0]; // "session=<token>"
const retentionDays = $('Read retention_days').first().json.retention_days;
return { json: { cookie, retentionDays } };
